Rewrite the following GNU C++14 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include"bits/stdc++.h"
#define F(i,j,n) for(register int i=j;i<=n;i++)
#define D(i,j,n) for(register int i=j;i>=n;i--)
#define ll unsigned long long
#define N 250010
using namespace std;
namespace io{
	const int L=(1<<19)+1;
	char ibuf[L],*iS,*iT,obuf[L],*oS=obuf,*oT=obuf+L-1,c,st[55];int f,tp;
	char gc(){
		if(iS==iT){
			iT=(iS=ibuf)+fread(ibuf,1,L,stdin);
			return iS==iT?EOF:*iS++;
		}
		return*iS++;
	}
	template<class I>void gi(I&x){
		for(f=1,c=gc();c<'0'||c>'9';c=gc())if(c=='-')f=-1;
		for(x=0;c<='9'&&c>='0';c=gc())x=x*10+(c&15);x*=f;
	}
};
using io::gi;
using io::gc;
int n,k,p,l,b[N];
ll x[26][N],f[N],g[N],a,d;
ll pw(ll x,int y=p-2){ll a=1;while(y){if(y&1)a=a*x%p;x=x*x%p;y>>=1;}return a;}
ll dfs(int k,int n){
	if(b[n]<k)return 0;
	if(k==1)return x[k][n]=g[n];
	if(x[k][n])return x[k][n];
	int t=0; 
	for(int i=n&(n-1);i;i=n&(i-1))if(b[i]>=k-1){
		x[k][n]+=dfs(k-1,i)*g[n^i];
		if(++t==18)t=0,x[k][n]%=p;
	}
	x[k][n]%=p; 
//	printf("%d %d %lld\n",k,n,x[k][n]);
	return x[k][n];
}
ll c(int n,int m){return f[n]*g[m]%p*g[n-m]%p;}
int main()
{
	#ifndef ONLINE_JUDGE
	freopen("255x.in","r",stdin);
	freopen("255x.out","w",stdout);
	#endif
	gi(n);gi(k);gi(p);
	F(i,1,n)b[i]=b[i>>1]+(i&1); 
	a=pw(k,n);
	if(n&1){printf("%d\n",a);return 0;}
	l=min(k,b[n]);
	f[0]=1;F(i,1,n)f[i]=f[i-1]*i%p;
	g[n]=pw(f[n]);D(i,n,1)g[i-1]=g[i]*i%p;
	D(i,l,1)d+=c(k,i)*dfs(i,n);
//	cout<<a<<endl<<d<<endl; 
	a=(a-d%p*f[n]%p+p)%p;
	printf("%lld\n",a);
//	printf("%.3lf\n",(double)clock()/CLOCKS_PER_SEC);
	return 0;
}

